  if (result === 'pass') {
    passed++;
  } else if (result === 'fail') {
    failed++;
  } else {
    skipped++;
  }
}

// Verdict: PASS only if nothing failed
const verdict = failed === 0 ? 'PASS' : 'FAIL';

console.log(`Passed: ${passed}`);
console.log(`Failed: ${failed}`);
console.log(`Skipped: ${skipped}`);
console.log(`Verdict: ${verdict}`);
```

